function extraSpaceRow(item={}){const options=Object.entries(extraSpaceKinds).map(([key,label])=>`<option value="${key}" ${item.kind===key?'selected':''}>${label}</option>`).join('');return `<div class="requirement-row" data-extra-id="${esc(item.id||id())}"><select data-extra="kind" aria-label="Space type">${options}</select><input data-extra="count" type="number" min="1" max="30" value="${Number(item.count)||1}" aria-label="Quantity"><input data-extra="seats" type="number" min="0" max="100" value="${Number(item.seats)||0}" aria-label="Seats each"><select data-extra="priority" aria-label="Priority"><option value="must" ${item.priority!=='preferred'?'selected':''}>Must</option><option value="preferred" ${item.priority==='preferred'?'selected':''}>Preferred</option></select><button type="button" class="btn" data-remove-row="extra">Remove</button></div>`}
function relationRow(item={}){const options=Object.entries(relationKinds).map(([key,label])=>`<option value="${key}" ${item.rule===key?'selected':''}>${label}</option>`).join('');return `<div class="requirement-row relation-row" data-relation-id="${esc(item.id||id())}"><input data-relation="from" value="${esc(item.from||'')}" placeholder="Space / group" aria-label="Space or group"><select data-relation="rule" aria-label="Relationship">${options}</select><input data-relation="to" value="${esc(item.to||'')}" placeholder="Other space (if relevant)" aria-label="Other space"><select data-relation="priority" aria-label="Priority"><option value="must" ${item.priority!=='preferred'?'selected':''}>Must</option><option value="preferred" ${item.priority==='preferred'?'selected':''}>Preferred</option></select><button type="button" class="btn" data-remove-row="relation">Remove</button></div>`}
function departmentRow(item={}){const options=Object.entries(activityKinds).map(([key,label])=>`<option value="${key}" ${item.activity===key?'selected':''}>${label}</option>`).join('');return `<div class="requirement-row department-row" data-department-id="${esc(item.id||id())}"><input data-department="name" value="${esc(item.name||'')}" placeholder="Department name" aria-label="Department name" maxlength="100"><input data-department="assigned" type="number" min="0" max="1000" value="${Number(item.assigned)||0}" aria-label="Assigned staff"><input data-department="peakOnsite" type="number" min="0" max="1000" value="${Number(item.peakOnsite)||0}" aria-label="Peak onsite staff"><select data-department="activity" aria-label="Primary activity">${options}</select><button type="button" class="btn" data-remove-row="department">Remove</button></div>`}
function tradeoffRow(item={}){const targets=Object.entries(tradeoffTargets).map(([key,label])=>`<option value="${key}" ${item.target===key?'selected':''}>${label}</option>`).join(''),actions=Object.entries(tradeoffActions).map(([key,label])=>`<option value="${key}" ${item.action===key?'selected':''}>${label}</option>`).join('');return `<div class="requirement-row tradeoff-row" data-tradeoff-id="${esc(item.id||id())}"><select data-tradeoff="target" aria-label="Target space">${targets}</select><select data-tradeoff="action" aria-label="Allowed tradeoff">${actions}</select><input data-tradeoff="minimum" type="number" min="0" max="1000" value="${Number(item.minimum)||0}" aria-label="Minimum quantity if reduced"><input data-tradeoff="alternative" value="${esc(item.alternative||'')}" placeholder="Alternative / condition" aria-label="Alternative or condition" maxlength="200"><button type="button" class="btn" data-remove-row="tradeoff">Remove</button></div>`}
function answerReviewHtml(b){const names={requested:'Requested', 'not-needed':'Explicitly not needed',unknown:'Not mentioned','needs-clarification':'Needs clarification'};return `<p>“Not mentioned” is not the same as “not needed”. For an unmentioned optional item, you may confirm it is not needed; otherwise it stays open in the result.</p><table class="broker-table"><thead><tr><th>Need</th><th>Extracted value</th><th>Customer statement</th></tr></thead><tbody>${Object.entries(intakeFields).map(([key,label])=>{const state=b.intakeAnswers?.[key]||'unknown',value=state==='requested'?(intakeBooleans.has(key)?'Required':b[key]):'—',select=state==='unknown'&&key!=='roomSeats'?`<select data-answer="${key}" aria-label="${esc(label)} status"><option value="unknown">Not mentioned</option><option value="not-needed">Confirm not needed</option></select>`:esc(names[state]||state);return `<tr><td>${esc(label)}</td><td>${esc(value)}</td><td>${select}</td></tr>`}).join('')}</tbody></table>`}
function collectReviewAnswers(base,host){const answers={...(base||{})};for(const input of $(host).querySelectorAll('[data-answer]'))answers[input.dataset.answer]=input.value;if(answers.meetingRooms==='not-needed')answers.roomSeats='not-needed';return answers}
