function collectExtraSpaces(){return [...$('#extraSpaceRows').querySelectorAll('[data-extra-id]')].map(row=>({id:row.dataset.extraId,kind:row.querySelector('[data-extra="kind"]').value,count:Number(row.querySelector('[data-extra="count"]').value),seats:Number(row.querySelector('[data-extra="seats"]').value),priority:row.querySelector('[data-extra="priority"]').value})).filter(item=>item.count>0)}
function collectRelations(){return [...$('#relationRows').querySelectorAll('[data-relation-id]')].map(row=>({id:row.dataset.relationId,from:row.querySelector('[data-relation="from"]').value.trim(),rule:row.querySelector('[data-relation="rule"]').value,to:row.querySelector('[data-relation="to"]').value.trim(),priority:row.querySelector('[data-relation="priority"]').value})).filter(item=>item.from)}
function collectDepartments(){return [...$('#departmentRows').querySelectorAll('[data-department-id]')].map(row=>({id:row.dataset.departmentId,name:row.querySelector('[data-department="name"]').value.trim(),assigned:Number(row.querySelector('[data-department="assigned"]').value),peakOnsite:Number(row.querySelector('[data-department="peakOnsite"]').value),activity:row.querySelector('[data-department="activity"]').value})).filter(item=>item.name)}
function collectTradeoffs(){return [...$('#tradeoffRows').querySelectorAll('[data-tradeoff-id]')].map(row=>({id:row.dataset.tradeoffId,target:row.querySelector('[data-tradeoff="target"]').value,action:row.querySelector('[data-tradeoff="action"]').value,minimum:Number(row.querySelector('[data-tradeoff="minimum"]').value),alternative:row.querySelector('[data-tradeoff="alternative"]').value.trim()}))}
