function syncBrokerBrief(){if(!P.broker)return;const b=P.broker;$('#briefPeople').value=b.people;$('#briefMeeting').value=b.meetingRooms*b.roomSeats;$('#briefPhone').value=b.phones;$('#briefMode').value=b.mode||'hybrid'}
// Fixed geometry makes every MVP run comparable, including briefs that do not fit.
const mvpSpaces = [
  {id:'compact',name:'Small open office',width:12000,height:9000,fit:'No columns',note:'North windows and a clear rectangular floor.',columns:[],blocked:[],openings:[
    {type:'door',wall:'west',x:0,y:4500},{type:'exit',wall:'east',x:12000,y:4500},
    {type:'window',wall:'north',x:3000,y:0},{type:'window',wall:'north',x:8500,y:0}]},
  {id:'balanced',name:'Mid-size office with columns',width:18000,height:12000,fit:'Two columns',note:'Two columns, a service zone and windows on two sides.',columns:[[6300,4200],[12000,7800]],blocked:[[0,0,3000,2500]],openings:[
    {type:'door',wall:'west',x:0,y:6000},{type:'exit',wall:'east',x:18000,y:6000},
    {type:'window',wall:'north',x:4500,y:0},{type:'window',wall:'north',x:13500,y:0},{type:'window',wall:'west',x:0,y:9500}]},
  {id:'spacious',name:'Large office with fixed core',width:24000,height:16000,fit:'Fixed core',note:'Four columns, a fixed corner zone and two marked exits.',columns:[[6000,4800],[12000,4800],[6000,11200],[12000,11200]],blocked:[[19000,12000,24000,16000]],openings:[
    {type:'door',wall:'west',x:0,y:8000},{type:'exit',wall:'east',x:24000,y:8000},{type:'exit',wall:'east',x:24000,y:2500},
    {type:'window',wall:'north',x:4500,y:0},{type:'window',wall:'north',x:15500,y:0},{type:'window',wall:'south',x:7000,y:16000}]}
];
function simulatedCandidates(){return mvpSpaces.map(space=>({...space,area:space.width*space.height/1e6}))}
function makeSimulationProject(candidate,brief){
  const project=fresh(`${brief.client||'Sample client'} · ${candidate.name}`,candidate.width,candidate.height,{kind:'simulated',label:candidate.name,fixtureId:candidate.id,fixtureVersion:MVP_FIXTURE_VERSION});
  project.broker=normalizeBrokerBrief({...brief,address:`SIMULATED · ${candidate.name}`,area:candidate.area,areaUnit:'sqm'});
  const walls={north:project.objects[0].id,east:project.objects[1].id,south:project.objects[2].id,west:project.objects[3].id};
  for(const opening of candidate.openings)project.objects.push({id:id(),type:opening.type,x:opening.x,y:opening.y,wallId:walls[opening.wall]});
  for(const [x,y] of candidate.columns)project.objects.push({id:id(),type:'column',x:x-300,y:y-300,x2:x+300,y2:y+300});
  for(const [x,y,x2,y2] of candidate.blocked)project.objects.push({id:id(),type:'blocked',x,y,x2,y2});
  return project;
}
function previewSimulation(candidate,brief){
  const project=makeSimulationProject(candidate,brief),previous=P,mode=brief.mode||'hybrid',patterns=['spine','core','perimeter','neighborhood'];
  try{
    P=project;
    const people=Math.max(4,Number(brief.people)||36),meeting=Math.max(0,Number(brief.meetingRooms)*Number(brief.roomSeats)||0),phone=Math.max(0,Number(brief.phones)||0);
    const drafts=patterns.map(pattern=>concept(pattern,people,meeting,phone,mode==='private'?'private':'hybrid'));
    drafts.sort((a,b)=>draftScore(a,project.broker,mode)-draftScore(b,project.broker,mode)||patterns.indexOf(a.layoutPattern)-patterns.indexOf(b.layoutPattern));
    const best=drafts[0];project.drafts=drafts.slice(0,3);project.activeDraft=best.id;project.objects=best.objects;project.furniture=best.furniture;project.site.confirmed=true;
    const rows=brokerAssessment(project).rows;
    return {best:best.label,pattern:best.layoutPattern,thumbnail:comparisonThumbnail(best),rows,gaps:rows.filter(row=>row.status==='Shortfall'),unassessed:rows.filter(row=>row.status==='Not assessed').length,clarify:rows.filter(row=>row.status==='Needs review').length,conceptReview:rows.filter(row=>row.status==='Placed · concept').length};
  }finally{P=previous}
}
let simulationPreviewCache={key:'',results:[]};
function simulationPreviews(brief){const key=JSON.stringify(brief);if(simulationPreviewCache.key!==key)simulationPreviewCache={key,results:simulatedCandidates().map(candidate=>previewSimulation(candidate,brief))};return simulationPreviewCache.results}
function decisionSnapshot(brief,previews,selectedId,reason){
  const candidates=simulatedCandidates(),chosen=candidates.find(candidate=>candidate.id===selectedId),explanation=String(reason||'').trim();
  if(!chosen||!explanation||explanation.length>500||previews.length!==candidates.length)return null;
  return {version:1,createdAt:new Date().toISOString(),plannerVersion:DECISION_PLANNER_VERSION,brief:JSON.parse(JSON.stringify(normalizeBrokerBrief(brief))),recommendedSiteId:selectedId,reason:explanation,sites:candidates.map((candidate,index)=>({fixtureId:candidate.id,fixtureVersion:MVP_FIXTURE_VERSION,name:candidate.name,width:candidate.width,height:candidate.height,bestLabel:previews[index].best,bestPattern:previews[index].pattern,rows:JSON.parse(JSON.stringify(previews[index].rows))}))};
}
function validDecision(value){return value?.version===1&&typeof value.createdAt==='string'&&typeof value.reason==='string'&&value.reason.length<=500&&value.brief?.requirements?.version>=2&&Array.isArray(value.sites)&&value.sites.length===3&&value.sites.every(site=>mvpSpaces.some(fixture=>fixture.id===site.fixtureId)&&typeof site.name==='string'&&typeof site.bestLabel==='string'&&Number.isFinite(site.width)&&Number.isFinite(site.height)&&site.width>0&&site.height>0&&Array.isArray(site.rows)&&site.rows.length<=100&&site.rows.every(row=>row&&typeof row.name==='string'&&typeof row.status==='string'))&&value.sites.some(site=>site.fixtureId===value.recommendedSiteId)}
function decisionContinueIssue(snapshot){
  if(!validDecision(snapshot))return 'This saved comparison is incomplete. It can be read, but cannot create a new layout.';
  if(snapshot.plannerVersion!==DECISION_PLANNER_VERSION)return 'The layout engine has changed since this report was saved. Start a fresh comparison before regenerating.';
  if(snapshot.brief.requirements.version!==DECISION_BRIEF_VERSION)return 'The customer needs format has changed since this report was saved. Start a fresh comparison before regenerating.';
  const selected=snapshot.sites.find(site=>site.fixtureId===snapshot.recommendedSiteId),fixture=mvpSpaces.find(site=>site.id===snapshot.recommendedSiteId);
  if(!fixture||selected.fixtureVersion!==MVP_FIXTURE_VERSION||selected.width!==fixture.width||selected.height!==fixture.height)return 'The selected sample space has changed since this report was saved. Start a fresh comparison before regenerating.';
  return '';
}
function loadDecision(){try{const value=JSON.parse(localStorage.getItem(DECISION_STORE));return validDecision(value)?value:null}catch{return null}}
savedDecision=loadDecision();
function renderDecisionButton(){const hidden=!savedDecision||readOnly||decisionReadOnly;$('#decisionOpen').hidden=hidden;$('#decisionWelcome').hidden=hidden}
function decisionSummary(snapshot){const brief=snapshot.brief,chosen=snapshot.sites.find(site=>site.fixtureId===snapshot.recommendedSiteId),stamp=new Date(snapshot.createdAt),date=Number.isNaN(stamp.getTime())?'Time unavailable':stamp.toLocaleString();
  const chosenGaps=chosen.rows.filter(row=>row.status==='Shortfall').map(row=>row.name),chosenOpen=chosen.rows.filter(row=>['Needs review','Not assessed'].includes(row.status)).map(row=>row.name),chosenConcept=chosen.rows.filter(row=>row.status==='Placed · concept').map(row=>row.name);
  const siteRows=snapshot.sites.map(site=>{const gaps=site.rows.filter(row=>row.status==='Shortfall'),unknown=site.rows.filter(row=>row.status==='Not assessed').length,review=site.rows.filter(row=>row.status==='Needs review').length,concept=site.rows.filter(row=>row.status==='Placed · concept').length,questions=unknown+review;return `<tr><td>${esc(site.name)}${site.fixtureId===snapshot.recommendedSiteId?' · follow-up choice':''}</td><td>${(site.width/1000).toFixed(1)} × ${(site.height/1000).toFixed(1)} m</td><td>${esc(site.bestLabel)}</td><td>${gaps.length?esc(gaps.map(row=>row.name).join(', ')):'No counted gap'}</td><td>${questions?`${questions} to clarify`:'No client questions'} · ${concept} concept placement${concept===1?'':'s'} to verify</td></tr>`}).join('');
  const details=snapshot.sites.map(site=>`<details><summary>${esc(site.name)} · requirement trace</summary><table class="broker-table"><thead><tr><th>Need</th><th>Requested</th><th>Concept result</th><th>Status</th></tr></thead><tbody>${site.rows.map(row=>`<tr><td>${esc(row.name)}</td><td>${esc(row.required)}</td><td>${esc(row.actual)}</td><td>${esc(row.status)}</td></tr>`).join('')}</tbody></table></details>`).join('');
  return `<div class="eyebrow">Saved comparison · ${esc(date)}</div><h1>Office shortlist decision</h1><p>${esc(brief.client||'Sample client')} · ${esc(brief.people)} requested workstations · ${esc(brief.meetingRooms)} meeting rooms · ${esc(brief.offices)} private offices</p><p><b>Continue investigating:</b> ${esc(chosen.name)}. ${esc(snapshot.reason)}</p><div class="notice"><b>Next checks for this space</b><p>${chosenGaps.length?`Resolve counted shortfalls: ${esc(chosenGaps.join(', '))}.`:'No counted shortfall in the first-ranked concept; this is not a fit verdict.'}</p><p>${chosenOpen.length?`Clarify unconfirmed or unassessed needs: ${esc(chosenOpen.join(', '))}.`:'No unconfirmed or unassessed needs in this saved brief.'}</p>${chosenConcept.length?`<p>Validate concept placements on a measured plan: ${esc(chosenConcept.join(', '))}.</p>`:''}<p>Verify measured dimensions, access and professional requirements before committing.</p></div><p class="empty">This is a frozen comparison using ${esc(snapshot.plannerVersion)} and the saved customer brief. Choosing a property for follow-up does not mean it fits, is code-compliant, or is ready for construction.</p><table class="broker-table"><thead><tr><th>Simulated space</th><th>Fixed rectangle</th><th>First-ranked concept</th><th>Hard requirement gaps</th><th>Open checks</th></tr></thead><tbody>${siteRows}</tbody></table>${details}`;
}
let decisionReturn=null;
function showDecisionReport(returnTo=null){if(!savedDecision)return;decisionReturn=returnTo;$('#decisionContent').innerHTML=decisionSummary(savedDecision);$('#decisionContent h1').insertAdjacentHTML('afterend',`<p class="notice">${decisionReadOnly?'This is a saved shortlist, not a property approval.':'Step 2 complete: you selected one space for follow-up. Next, compare three layouts for that same space.'}</p>`);$('#decisionContinueError').textContent='';$('#decisionShare').hidden=decisionReadOnly;$('#decisionClose').hidden=decisionReadOnly;$('#decisionContinue').hidden=decisionReadOnly;$('#simulationModal').hidden=true;$('#brokerReport').hidden=true;$('#decisionModal').hidden=false}
