  for(const tradeoff of b.requirements.tradeoffs)rows.push({name:`Tradeoff · ${tradeoffTargets[tradeoff.target]}`,required:`${tradeoffActions[tradeoff.action]}${tradeoff.action==='reduce'?` · minimum ${tradeoff.minimum}`:''}${tradeoff.alternative?` · ${tradeoff.alternative}`:''}`,actual:'Not applied',status:'Not assessed'});
